    # Function to check if a substring is lexicographically smaller
    def is_smaller(sub1, sub2):
        return sub1 < sub2

    # Precompute the smallest suffix starting from each position
    smallest_suffix = [None] * n
    smallest_suffix[-1] = n - 1
    for i in range(n - 2, -1, -1):
